#include <array>
#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

void pixelCounts(std::vector<int> const& image, std::array<size_t, 256> &bins) {
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 256>> local(static_cast<size_t>(max_threads));
    for (auto &a : local) a.fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(image.size()); ++i) {
            const int v = image[static_cast<size_t>(i)];
            // Assuming image values are 0..255 as stated; clamp defensively.
            const unsigned idx = (v < 0) ? 0u : (v > 255 ? 255u : static_cast<unsigned>(v));
            lb[idx] += 1;
        }

        #pragma omp for schedule(static)
        for (int b = 0; b < 256; ++b) {
            size_t sum = 0;
            for (int t = 0; t < max_threads; ++t) {
                sum += local[static_cast<size_t>(t)][static_cast<size_t>(b)];
            }
            bins[static_cast<size_t>(b)] = sum;
        }
    }
}
